-- Step 1 (Production): Create job_slug_redirects + insert 1,046 matched + 18 ambiguous redirects
-- Re-verifies against PRODUCTION public.jobs before inserting:
--   - from_slug must NOT be a live seo_slug in public.jobs
--   - to_slug MUST exist in public.jobs
BEGIN;

CREATE TABLE IF NOT EXISTS public.job_slug_redirects (
  from_slug text PRIMARY KEY,
  to_slug text NOT NULL,
  source_job_id uuid,
  target_job_id uuid,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.job_slug_redirects ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public read access for job_slug_redirects" ON public.job_slug_redirects;
CREATE POLICY "Public read access for job_slug_redirects"
  ON public.job_slug_redirects
  FOR SELECT
  USING (true);

GRANT SELECT ON public.job_slug_redirects TO anon, authenticated, service_role;

CREATE TEMP TABLE _step1_candidates (
  from_slug text PRIMARY KEY,
  to_slug text NOT NULL,
  target_job_id uuid
) ON COMMIT DROP;

ON CONFLICT (from_slug) DO NOTHING;

CREATE TEMP TABLE _step1_verified ON COMMIT DROP AS
SELECT
  c.from_slug,
  c.to_slug,
  t.id AS target_job_id,
  EXISTS (
    SELECT 1 FROM public.jobs l
    WHERE l.seo_slug = c.from_slug
      AND l.is_active = true
      AND coalesce(l.job_status, '') NOT IN ('closed', 'expired')
      AND coalesce(l.status, '') NOT IN ('expired', 'closed', 'filled')
      AND (l.expires_at IS NULL OR l.expires_at > now())
      AND (l.application_deadline IS NULL OR l.application_deadline > now())
  ) AS from_is_live,
  (t.id IS NOT NULL) AS to_exists
FROM _step1_candidates c
LEFT JOIN LATERAL (
  SELECT j.id FROM public.jobs j
  WHERE j.seo_slug = c.to_slug
  ORDER BY j.created_at ASC, j.id ASC
  LIMIT 1
) t ON true;

WITH inserted AS (
  SELECT from_slug, to_slug, target_job_id
  FROM _step1_verified
  WHERE NOT from_is_live
    AND to_exists
    AND from_slug <> to_slug
  ON CONFLICT (from_slug) DO NOTHING
  RETURNING from_slug
)
SELECT
  (SELECT count(*) FROM _step1_candidates) AS total_candidates,
  (SELECT count(*) FROM inserted) AS inserted_count,
  (SELECT count(*) FROM _step1_verified WHERE from_is_live) AS skipped_from_is_live,
  (SELECT count(*) FROM _step1_verified WHERE NOT to_exists) AS skipped_to_missing,
  (SELECT count(*) FROM public.job_slug_redirects) AS total_in_table;

COMMIT;
